            state.add("z")
        err = e.value
        expected_error = InputParseError("z", 0, "ba")
        if error_for_most_recent_input:
            assert (
                err.error_for_most_recent_input
                == expected_error.error_for_most_recent_input
            )
        else:
            assert str(err) == str(expected_error)

