// Temporary harness: emits the same records as /tmp/diff_python.py so the two
// implementations can be diffed. Not part of the test suite.
import { readFileSync, writeFileSync } from 'node:fs';
import { it } from 'vitest';
import { GBNF } from '../src/index.js';
import type { ParseState } from '../src/index.js';

interface CorpusEntry {
  key: string;
  grammar: string;
  cases: string[];
}

const corpus: {
  alphabet: string[];
  maxPrefix: number;
  grammars: CorpusEntry[];
} = JSON.parse(readFileSync('/tmp/corpus.json', 'utf-8'));

const rulesOf = (state: ParseState) => [...state].map((rule) => rule.toDict());

const describeError = (err: unknown): string => {
  const e = err as Error;
  return `${e.name}: ${e.toString()}`;
};

it('emits differential records', () => {
  const records: unknown[] = [];
  for (const entry of corpus.grammars) {
    const { key, grammar } = entry;
    for (const [caseIdx, testCase] of entry.cases.entries()) {
