        if isinstance(p.get('r'), list): p['r'] = sortr(p['r'])
    return r
classes = collections.Counter()
examples = {}
for i,(x,y) in enumerate(zip(a,b)):
    nx, ny = norm(x), norm(y)
    if nx == ny:
        classes['order-only' if x != y else 'identical'] += 1
