            elif 'err' not in px and 'err' in py_: kinds.add('py-ok-ts-err')
            else: kinds.add('other')
    key = ','.join(sorted(kinds))
    classes[key] += 1
    examples.setdefault(key, i)
for k,v in classes.most_common(): print(f'{v:6d}  {k}')
