MAX_INLINE = 76


def js_string(s):
    out = ["'"]
    for ch in s:
        if ch == "'":
            out.append("\\'")
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        else:
            out.append(ch)
    out.append("'")
    return "".join(out)


def js_key(key):
    return key if key.isidentifier() else js_string(key)


def dump(value, indent, width=MAX_INLINE):
    """Emit a TypeScript literal, keeping anything that fits on one line inline."""
    flat = flatten(value)
    if len(flat) + indent <= width:
        return flat
    pad = " " * (indent + 2)
    if isinstance(value, (list, tuple)):
        items = [f"{pad}{dump(v, indent + 2, width)}" for v in value]
        return "[\n" + ",\n".join(items) + f"\n{' ' * indent}]"
    if isinstance(value, dict):
        items = [
            f"{pad}{js_key(k)}: {dump(v, indent + 2, width)}" for k, v in value.items()
        ]
        return "{\n" + ",\n".join(items) + f"\n{' ' * indent}}}"
    return flat


def flatten(value):
    if isinstance(value, str):
        return js_string(value)
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return json.dumps(value)
    if isinstance(value, (list, tuple)):
        return "[" + ", ".join(flatten(v) for v in value) + "]"
    if isinstance(value, dict):
        return "{ " + ", ".join(f"{js_key(k)}: {flatten(v)}" for k, v in value.items()) + " }"
    raise TypeError(type(value))


def lit(value, indent=0):
    return dump(value, indent)

